"""Build the nine standalone HTML pages from the preserved design and shared shell."""
from pathlib import Path
import html
import json

ROOT = Path(__file__).resolve().parent.parent
sn = json.loads((ROOT / 'templates/sections.json').read_text(encoding='utf-8'))


def tx(ru, en):
    return f'<span data-ru="{html.escape(ru,quote=True)}" data-en="{html.escape(en,quote=True)}">{html.escape(ru)}</span>'


def icon(name):
    return f'<span data-icon="{name}"></span>' if name else ''


def btn(id, ru, en, ic='', cls='btn outline', extra=''):
    return f'<button id="{id}" class="{cls}" {extra}>{icon(ic)}{tx(ru,en)}</button>'


def label(ru, en, control):
    return '<label>' + tx(ru,en) + control + '</label>'


def lead(ru, en, subru, suben):
    return '<section class="wrap page-lead"><div class="eyebrow">' + tx('Омск Гид / Ваше путешествие','Omsk Guide / Your journey') + '</div><h1>' + tx(ru,en) + '</h1><p>' + tx(subru,suben) + '</p></section>'


def panel(ru, en, content):
    return '<section class="panel"><h2>' + tx(ru,en) + '</h2>' + content + '</section>'


categories = [('walk','Прогулки / Walks'),('food','Еда / Food'),('culture','Культура / Culture'),('coffee','Кофе / Coffee'),('bar','Бары / Bars'),('family','Семья / Family')]
nav = [('places','Места','Places'),('routes','Маршруты','Routes'),('guide','Путеводитель','Guide'),('events','Афиша','Events'),('journal','Личное','My trip'),('reviews','Отзывы','Reviews'),('about','О боте','About')]
